[ExtensionOf(classStr(WhsWorkExecuteDisplayUserDirected))]
final internal class WhsWorkExecuteDisplayUserDirected_AGA_Extension
{
}

Method.Source:
/// <summary>
/// Builds the form controls for standard item quantity entry.
/// Standard items go directly to quantity entry, bypassing the old step 2 form.
/// </summary>
/// <returns>Container with quantity entry form controls</returns>
protected container buildAgaStandardItemQtyControls()
{
    container ret;
    str itemId = '';

    // Get item ID from pass
    if (pass && pass.exists('AgaCurrentItem'))
    {
        itemId = pass.lookup('AgaCurrentItem');
    }

    // Build quantity entry form for standard items
    ret = this.buildControl(
        "@WAX:Quantity",
        WHSRFControlType::Input,
        "AgaQty",
        "",
        strFmt("@WAX:EnterQtyForItem", itemId),
        ""
    );

    return ret;
}

/// <summary>
/// Helper method to build a control container.
/// </summary>
private container buildControl(
    str _label,
    WHSRFControlType _controlType,
    str _name,
    str _data,
    str _message,
    str _placeholder)
{
    container ret;

    // Build control container - simplified version
    // In real implementation, this would use proper control building logic
    ret = [_label, _controlType, _name, _message, _placeholder, _data];

    return ret;
}
